TLM.f("Sancti/07-21",{"officium":"S. Praxedis Virginis","rule":["vide C7a;","Gloria"],"fallback":"Commune/C7a","from":{"GradualeP":"Commune/C7a","Tractus":"Commune/C7a","Evangelium":"Commune/C7a","Offertorium":"Commune/C7a","Secreta":"Commune/C7a","Postcommunio":"Commune/C7a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 118:46-47"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Exáudi nos, Deus, salutáris noster: ut, sicut de beátæ Praxédis Vírginis tuæ festivitáte gaudémus; ita piæ devotiónis erudiámur afféctu."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 7:25-34"},{"k":"text","la":"Fratres: De virgínibus præcéptum Dómini non hábeo: consílium autem do, tamquam misericórdiam consecútus a Dómino, ut sim fidélis. Exístimo ergo hoc bonum esse propter instántem necessitátem, quóniam bo; num est hómini sic esse. Alligátus es uxóri? noli quǽrere solutiónem. Solútus es ab uxóre? noli quǽrere uxórem. Si autem accéperis uxórem, non peccásti. Et si núpserit virgo, non peccávit: tribulatiónem tamen carnis habébunt hujúsmodi. Ego autem vobis parce. Hoc ítaque dico, fratres: Tempus breve est: réliquum est, ut, et qui habent uxóres, tamquam non habéntes sint; et qui flent, tamquam non flentes; et qui gaudent, tamquam non gaudéntes; et qui emunt, tamquam non possidéntes; et qui utúntur hoc mundo, tamquam non utántur; prǽterit enim figúra hujus mundi. Volo autem vos sine sollicitúdine esse. Qui sine uxóre est, sollícitus est, quæ Dómini sunt, quómodo pláceat Deo. Qui autem cum uxóre est, sollícitus est, quæ sunt mundi, quómodo pláceat uxóri, et divísus est. Et múlier innúpta et virgo cógitat, quæ Dómini sunt, ut sit sancta córpore et spíritu: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 44:3; 44:5"},{"k":"text","la":"Diffúsa est grátia in labiis tuis: proptérea benedíxit te Deus in ætérnum."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et de ducet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Veni, Sponsa Christi, áccipe coronam, quam tibi Dóminus præparávit in ætérnum."},{"k":"ref","la":"Ps 44:8; 44:5"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, oleo lætítiæ præ consórtibus tuis."},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:44-52"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile est regnum cœlórum thesáuro abscóndito in agro: quem qui invénit homo, abscóndit, et præ gáudio illíus vadit, et vendit univérsa, quæ habet, et emit agrum illum. Íterum símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas. Invénta autem una pretiósa margaríta, ábiit, et véndidit ómnia, quæ hábuit, et emit eam. Íterum símile est regnum cœlórum sagénæ missæ in mare et ex omni génere píscium congregánti. Quam, cum impléta esset, educéntes, et secus litus sedéntes, elegérunt bonos in vasa, malos autem foras misérunt. Sic erit in consummatióne sǽculi: exíbunt Angeli, et separábunt malos de médio justórum, et mittent eos in camínum ignis: ibi erit fletus et stridor déntium. Intellexístis hæc ómnia? Dicunt ei: Etiam. Ait illis: Ideo omnis scriba doctus in regno cœlórum símilis est hómini patrifamílias, qui profert de thesáuro suo nova et vétera."}],"Offertorium":[{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum, et in sǽculum sǽculi."}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 13:45-46"},{"k":"text","la":"Símile est regnum cœlórum hómini negotiatóri, quærénti bonas margarítas: invénta autem una pretiósa margaríta, dedit ómnia sua, et comparávit eam."}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"29ee2b22ea82a27c":{"t":"<i>Pomolimo se</i>.\nUsliši nas, Bože Spasitelju naš, da kao što se radujemo svetkovini blažene Praksede, djevice tvoje, tako uznapredujemo u osjećaju odane pobožnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši nae, Bože, spasitelju naš, kao što se radu-jemo' o svetkovini blažene Praksede, Tvoje djevice, tako da rastemo i u pobožnoj bogoljubnosti, (pp G. n. '","knRef":"Kniewald 1942, str. 648–649 (snimka 325) (OCR)"},"135c5bf58bce477d":{"t":"Pogledaj, Gospodine, na darove svoga naroda, i daj mu osjetiti da mu koristi za spasenje ova žrtvena svečanost koju obavlja s pobožnom odanošću na čast tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
